 slider('adjustRegionFeather','Mềm viền vùng áp dụng',0,1);
 slider('adjustRegionX','Vị trí ngang vùng áp dụng',0,1);
 slider('adjustRegionY','Vị trí dọc vùng áp dụng',0,1);
 slider('adjustRegionRX','Nửa chiều dài vùng áp dụng',.015,1.2);
