 const actions=document.createElement('div');actions.className='adjust-scope-actions';for(const [label,fn]of [['Lấy vùng sáng/tối đang có',useCurrent],['Đưa vùng về giữa',()=>{P.adjustRegionX=P.adjustRegionY=.5;P.adjustRegionShow=true;P.adjustRegionPlaced=true;}]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=()=>act(label,fn);actions.append(b);}details.append(actions);
 const status=document.createElement('p');status.className='hint';status.setAttribute('role','status');details.append(status);
 const overlay=document.createElement('div');overlay.id='adjustScopeOverlay';overlay.setAttribute('role','group');overlay.setAttribute('aria-label','Vùng áp dụng màu và điều chỉnh');overlay.tabIndex=0;overlay.hidden=true;
