  const showing=editing();overlay.hidden=!showing||shape.value==='freehand';if(app.classList.contains('adjust-scope-positioning')!==showing)app.classList.toggle('adjust-scope-positioning',showing);window.RayRegionPaintUI?.sync();if(overlay.hidden)return;const g=bodyGeo();if(!g)return;const wr=wrap.getBoundingClientRect(),f=core.geometry(P);Object.assign(overlay.style,{left:g.ox-wr.left+f.cx*g.W*g.k+'px',top:g.oy-wr.top+f.cy*g.H*g.k+'px',width:f.rx*2*g.W*g.k+'px',height:f.ry*2*g.H*g.k+'px',transform:'translate(-50%,-50%) rotate('+(P.adjustRegionAngle||0)+'deg)'});
