 for(const [node,kind]of [[overlay,'move'],[size,'size'],[rotate,'rotate']])RayControls.bindDrag(node,{start(e){if(!editing()||kind==='move'&&(e.target===size||e.target===rotate))return;const g=bodyGeo();if(!g)return;window.RaySession?.record();const f=core.geometry(P),px=g.ox+f.cx*g.W*g.k,py=g.oy+f.cy*g.H*g.k;return{g,...f,angle:P.adjustRegionAngle||0,px,py,from:Math.atan2(e.clientY-py,e.clientX-px)*180/Math.PI};},move(s,e){if(kind==='move'){P.adjustRegionX=clamp(s.cx+(e.dx/(s.g.W*s.g.k)),0,1);P.adjustRegionY=clamp(s.cy+(e.dy/(s.g.H*s.g.k)),0,1);}else if(kind==='size'){const next=RayTone.resizeRegion(s,s.g.W,s.g.H,e.dx/s.g.k,e.dy/s.g.k,s.angle);P.adjustRegionRX=next.rx;P.adjustRegionRY=next.ry;}else P.adjustRegionAngle=((s.angle+Math.atan2(e.clientY-s.py,e.clientX-s.px)*180/Math.PI-s.from+540)%360)-180;P.adjustRegionPlaced=true;RayLayers.updateScope();sync();queue();},end(){window.RaySession?.record('Vị trí và hình dạng vùng áp dụng');}});
 overlay.addEventListener('keydown',e=>{if(e.target!==overlay||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();act('Dịch vùng áp dụng',()=>{const d=e.shiftKey?.02:.005;if(e.key==='ArrowLeft')P.adjustRegionX=clamp(P.adjustRegionX-d,0,1);if(e.key==='ArrowRight')P.adjustRegionX=clamp(P.adjustRegionX+d,0,1);if(e.key==='ArrowUp')P.adjustRegionY=clamp(P.adjustRegionY-d,0,1);if(e.key==='ArrowDown')P.adjustRegionY=clamp(P.adjustRegionY+d,0,1);});});
 const oldSync=syncControls;syncControls=function(...args){const r=oldSync.apply(this,args);sync();return r;};const oldDraw=draw;draw=function(...args){const r=oldDraw.apply(this,args);sync();return r;};const onTool=RayControls.onToolChange;RayControls.onToolChange=function(...args){const r=onTool.apply(this,args);sync();return r;};new MutationObserver(sync).observe(app,{attributes:true,attributeFilter:['class']});new MutationObserver(sync).observe(document.body,{attributes:true,attributeFilter:['data-editor-tool','data-adjust-section']});new ResizeObserver(sync).observe(wrap);window.RayAdjustScopeUI={sync,act,localChanged,localShared,visible:editing};sync();
